s['tables']=[table('Table 8.8 Summary of Three Concepts of Acids and Bases','جدول 8.8 تیزابوں اور اساسوں کے تین تصورات کا خلاصہ','جدول 8.8 د اسیدونو او القليو د دریو مفکورو لنډیز',[c('Concept','تصور','مفکوره'),c('Definition of acid','تیزاب کی تعریف','د اسید تعریف'),c('Definition of base','اساس کی تعریف','د القلي تعریف')],[[c('Arrhenius','آرہینئس','ارهینیوس'),c('H⁺ producer','H⁺ پیدا کرنے والا','H⁺ تولیدوونکی'),c('OH⁻ producer','OH⁻ پیدا کرنے والا','OH⁻ تولیدوونکی')],[c('Bronsted – Lowery','برونسٹڈ لوری','برونسټډ-لوري'),c('H⁺ donor','H⁺ عطا کنندہ','H⁺ ورکوونکی'),c('H⁺ acceptor','H⁺ قبول کنندہ','H⁺ منونکی')],[c('Lewis','لیوس','لیویس'),c('Electron pair acceptor','الیکٹران جوڑا قبول کنندہ','د الکترون جوړې منونکی'),c('Electron pair donor','الیکٹران جوڑا عطا کنندہ','د الکترون جوړې ورکوونکی')]])]
